import React, { useState, useEffect, useRef } from 'react';

interface PredefinedHelpModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectAction: (actionKey: string, params?: { crop?: string; quantity?: number; price?: number }) => void;
  language?: 'EN' | 'BN' | 'HI';
}

export const PredefinedHelpModal: React.FC<PredefinedHelpModalProps> = ({
  isOpen,
  onClose,
  onSelectAction,
  language = 'EN'
}) => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [feedback, setFeedback] = useState('');
  const recognitionRef = useRef<any>(null);

  const quickActions = [
    { key: 'prices', icon: 'payments', label: "Show today's market prices", desc: "View real-time mandi rates & AI demand alerts" },
    { key: 'sell', icon: 'add_circle', label: "Sell my produce", desc: "List crop in 3 simple steps" },
    { key: 'track', icon: 'local_shipping', label: "Track my orders", desc: "View live dispatch & logistics status" },
    { key: 'market', icon: 'analytics', label: "Market Intelligence", desc: "Forecast demand and fair rate analysis" }
  ];

  // Initialize Web Speech Recognition
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const recognition = new SpeechRecognition();
        recognition.continuous = false;
        recognition.interimResults = true;
        
        // Match language
        if (language === 'BN') {
          recognition.lang = 'bn-IN';
        } else if (language === 'HI') {
          recognition.lang = 'hi-IN';
        } else {
          recognition.lang = 'en-IN';
        }

        recognition.onstart = () => {
          setIsListening(true);
          setFeedback('Listening... Please speak (e.g. "Sell tomato", "Show prices", "Track orders")');
        };

        recognition.onresult = (event: any) => {
          const current = event.resultIndex;
          const text = event.results[current][0].transcript;
          setTranscript(text);
        };

        recognition.onerror = (event: any) => {
          console.error('Speech error:', event.error);
          setIsListening(false);
          setFeedback(`Voice error: ${event.error}. Please try again or tap an action below.`);
        };

        recognition.onend = () => {
          setIsListening(false);
        };

        recognitionRef.current = recognition;
      }
    }
  }, [language]);

  // When transcript updates and speech finishes, analyze intent
  useEffect(() => {
    if (transcript && !isListening) {
      handleVoiceCommand(transcript);
    }
  }, [isListening, transcript]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      setTranscript('');
      setFeedback('Initializing microphone...');
      try {
        if (!recognitionRef.current) {
          const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
          if (!SpeechRecognition) {
            setFeedback('Web Speech API is not supported in this browser. Please use Chrome/Edge or tap an option below.');
            return;
          }
        }
        recognitionRef.current?.start();
      } catch (err) {
        console.error(err);
        setFeedback('Could not start microphone. Please check permissions.');
      }
    }
  };

  const handleVoiceCommand = (text: string) => {
    const lower = text.toLowerCase();
    setFeedback(`Interpreted: "${text}"`);

    // Match keywords for Sell / List produce
    if (lower.includes('sell') || lower.includes('list') || lower.includes('bikri') || lower.includes('bechna') || lower.includes('produce') || lower.includes('crop')) {
      let detectedCrop = 'Tomato';
      if (lower.includes('potato') || lower.includes('alu') || lower.includes('aaloo')) detectedCrop = 'Potato';
      if (lower.includes('onion') || lower.includes('pyaj') || lower.includes('peyaj')) detectedCrop = 'Onion';
      if (lower.includes('rice') || lower.includes('chawal') || lower.includes('dhan')) detectedCrop = 'Rice';

      setFeedback(`Recognized command: "Sell Produce (${detectedCrop})". Launching wizard...`);
      setTimeout(() => {
        onSelectAction('sell', { crop: detectedCrop });
        onClose();
      }, 1000);
      return;
    }

    // Match keywords for Prices / Mandi rate
    if (lower.includes('price') || lower.includes('rate') || lower.includes('dam') || lower.includes('daam') || lower.includes('bhaav') || lower.includes('mandi')) {
      setFeedback('Recognized command: "Check Market Rates". Navigating...');
      setTimeout(() => {
        onSelectAction('prices');
        onClose();
      }, 1000);
      return;
    }

    // Match keywords for Orders / Tracking
    if (lower.includes('order') || lower.includes('track') || lower.includes('dispatch') || lower.includes('status') || lower.includes('delivery')) {
      setFeedback('Recognized command: "Track Orders". Navigating...');
      setTimeout(() => {
        onSelectAction('track');
        onClose();
      }, 1000);
      return;
    }

    // Match keywords for Market intelligence
    if (lower.includes('market') || lower.includes('demand') || lower.includes('forecast')) {
      setFeedback('Recognized command: "Market Intelligence". Navigating...');
      setTimeout(() => {
        onSelectAction('market');
        onClose();
      }, 1000);
      return;
    }

    setFeedback(`Heard: "${text}". Please tap an option below or speak clearly.`);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-end sm:items-center justify-center p-0 sm:p-4 animate-in fade-in duration-200">
      <div className="w-full max-w-[430px] bg-surface rounded-t-3xl sm:rounded-3xl p-5 border border-outline-variant shadow-2xl flex flex-col gap-4 max-h-[90vh] overflow-y-auto">
        
        {/* Header */}
        <div className="flex items-center justify-between border-b border-outline-variant pb-3">
          <div className="flex items-center gap-2.5">
            <div className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all ${
              isListening ? 'bg-red-600 text-white animate-bounce shadow-lg' : 'bg-primary-container text-on-primary'
            }`}>
              <span className="material-symbols-outlined text-[26px]">mic</span>
            </div>
            <div>
              <h3 className="text-[17px] font-extrabold text-on-surface">Voice Command Assistant</h3>
              <p className="text-[12px] text-on-surface-variant font-medium">Speak in English, Bengali, or Hindi</p>
            </div>
          </div>
          <button onClick={onClose} className="w-9 h-9 rounded-full flex items-center justify-center text-on-surface-variant hover:bg-surface-container-high">
            <span className="material-symbols-outlined text-[22px]">close</span>
          </button>
        </div>

        {/* Big Mic Button & Speech Feedback Panel */}
        <div className="bg-surface-container-low border border-outline-variant rounded-2xl p-4 flex flex-col items-center text-center gap-3">
          <button
            onClick={toggleListening}
            className={`w-20 h-20 rounded-full flex flex-col items-center justify-center transition-all transform active:scale-95 shadow-md ${
              isListening 
                ? 'bg-red-600 text-white ring-4 ring-red-300 animate-pulse' 
                : 'bg-primary text-white hover:bg-primary/90'
            }`}
          >
            <span className="material-symbols-outlined text-[36px]">
              {isListening ? 'graphic_eq' : 'mic'}
            </span>
            <span className="text-[10px] font-bold uppercase tracking-wider mt-0.5">
              {isListening ? 'Listening' : 'Tap to Talk'}
            </span>
          </button>

          <div className="flex flex-col gap-1 w-full">
            {transcript ? (
              <p className="text-[14px] font-extrabold text-primary bg-white py-2 px-3 rounded-xl border border-outline-variant">
                "{transcript}"
              </p>
            ) : null}

            <p className="text-[12px] font-bold text-on-surface-variant">
              {feedback || 'Tap the mic and speak: "Sell tomato", "Show prices", or "Track orders"'}
            </p>
          </div>
        </div>

        {/* Quick tap fallback suggestions */}
        <div className="flex flex-col gap-2">
          <span className="text-[11px] font-bold text-secondary uppercase tracking-wider px-1">
            Or Tap Quick Action
          </span>
          {quickActions.map(action => (
            <button
              key={action.key}
              onClick={() => {
                onSelectAction(action.key);
                onClose();
              }}
              className="p-3 bg-surface-container-lowest hover:bg-surface-container-low border border-outline-variant rounded-2xl flex items-center gap-3 text-left transition-all active:scale-98 shadow-xs"
            >
              <div className="w-10 h-10 rounded-xl bg-surface-container-high text-primary flex items-center justify-center shrink-0">
                <span className="material-symbols-outlined text-[22px]">{action.icon}</span>
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[14px] font-bold text-on-surface">{action.label}</p>
                <p className="text-[11px] text-on-surface-variant truncate font-medium">{action.desc}</p>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};
